{"command": "# Get unique senders from promo emails - sample 30 to understand the landscape
python3 -c "
import json, subprocess, sys

# Already have the promo message IDs from the listing
promo_ids = ['e7b1fdcc65514275','936ca5b74a7242e1','12d35128d1504619','b1fa8d11564544fe','124aa171acd849fb','817dd5cd933445e5','47d751bbec0a43f7','ad48f9b13ec44452','29ec4c153a4641ac','27a745b803e9434a','e3a6eeeb593f4b0b','e697ffa83b3e43e0','68340664f52643dc','51f7c599b2a845f9','4cd7cb82e6e542a9','e9f19a0d87d54191','e72a573e0d214194','c0546cb7db634ed0','35ecffa80bac4b04','584c2876b1a24fcc','9b1c79fb85ac4c71','4ecee9cc16324376','23d56ba7d69c4717','4e3bc8174add4416','03aa0c7f412b420a','f1837c5775884f67','72b3d7028f444a2e','7bfaaa5f62a74242','c726a7bff06f4c96','b51eca04b3214a93']

for mid in promo_ids:
    result = subprocess.run(['gws','gmail','users','messages','get','--params',json.dumps({'userId':'me','id':mid,'format':'metadata','metadataHeaders':['From','Subject']})], capture_output=True, text=True, timeout=10)
    try:
        d = json.loads(result.stdout)
        h = {x['name']:x['value'] for x in d.get('payload',{}).get('headers',[])}
        print(f\"{h.get('From','?')}\t{h.get('Subject','?')}\")
    except:
        pass
" 2>/dev/null", "timeout": 60}

{"command": "# Check for starred promos or updates to exclude
gws gmail users messages list --params '{"userId": "me", "labelIds": "STARRED", "maxResults": 500}' --page-all --page-limit 10 --format json 2>/dev/null | python3 -c "
import json,sys
data = sys.stdin.read()
# Parse NDJSON lines
starred_ids = set()
for line in data.strip().split('\n'):
    try:
        d = json.loads(line)
        for m in d.get('messages',[]):
            starred_ids.add(m['id'])
    except:
        pass
print(f'Starred message IDs: {len(starred_ids)}')
print(list(starred_ids)[:20] if starred_ids else 'None found')
"", "timeout": 15}

{"command": "# Check for starred emails among ALL categories to be safe, save to file
gws gmail users messages list --params '{"userId": "me", "labelIds": "STARRED", "maxResults": 500}' --page-all --page-limit 20 --format json 2>/dev/null | python3 -c "
import json, sys
starred = set()
for line in sys.stdin:
    try:
        d = json.loads(line)
        for m in d.get('messages', []):
            starred.add(m['id'])
    except:
        pass
with open('/tmp/all_starred_ids.json', 'w') as f:
    json.dump(list(starred), f)
print(f'Total starred: {len(starred)}')
"", "timeout": 30}

{"command": "# Check for IMPORTANT labeled emails
gws gmail users messages list --params '{"userId": "me", "labelIds": "IMPORTANT", "maxResults": 500}' --page-all --page-limit 20 --format json 2>/dev/null | python3 -c "
import json, sys
important = set()
for line in sys.stdin:
    try:
        d = json.loads(line)
        for m in d.get('messages', []):
            important.add(m['id'])
    except:
        pass
with open('/tmp/all_important_ids.json', 'w') as f:
    json.dump(list(important), f)
print(f'Total important: {len(important)}')
"", "timeout": 30}

