{"command": "# Check for starred promos or updates to exclude
gws gmail users messages list --params '{"userId": "me", "labelIds": "STARRED", "maxResults": 500}' --page-all --page-limit 10 --format json 2>/dev/null | python3 -c "
import json,sys
data = sys.stdin.read()
# Parse NDJSON lines
starred_ids = set()
for line in data.strip().split('\n'):
    try:
        d = json.loads(line)
        for m in d.get('messages',[]):
            starred_ids.add(m['id'])
    except:
        pass
